class Solution {
    public int digitsCount(int d, int low, int high) {
        long ans = 0;
        char t = (char) ('0' + d);
        for (long x = low; x <= high; x++) {
            String s = Long.toString(x);
            for (char c : s.toCharArray()) if (c == t) ans++;
        }
        return (int) ans;
    }
}

