class Solution:
    def digitsCount(self, d: int, low: int, high: int) -> int:
        def count(n: int) -> int:
            if n <= 0:
                return 0
            ans, pow_ = 0, 1
            while pow_ <= n:
                hi, cur, lo = n // (pow_ * 10), (n // pow_) % 10, n % pow_
                if cur > d:
                    ans += (hi + 1) * pow_
                elif cur == d:
                    ans += hi * pow_ + lo + 1
                else:
                    ans += hi * pow_
                if d == 0 and hi > 0:
                    ans -= pow_
                pow_ *= 10
            return ans
        return count(high) - count(low - 1)

