        if (n <= 0) return 0;
        long long ans = 0, pw = 1;
        while (pw <= n) {
            long long hi = n / (pw * 10), cur = (n / pw) % 10, lo = n % pw;
            if (cur > d) ans += (hi + 1) * pw;
            else if (cur == d) ans += hi * pw + lo + 1;
            else ans += hi * pw;
            if (d == 0 && hi > 0) ans -= pw;
            pw *= 10;
        }
        return ans;
    }
public:
